/**
 * Opt-in Node host adapter for the Node-compatible OS capability.
 *
 * Values are obtained from Node.js rather than captured when this package is
 * built, so the guest observes the machine that instantiates the component.
 */
import nodeOs from "node:os";
import { captureOsCall, serializeNetworkInterfaces, serializeOsCpus, serializeOsStaticProperties, serializeUserInfo, } from "./os/host-utils.js";
export const getStaticProperties = () => captureOsCall(() => serializeOsStaticProperties(nodeOs.EOL, nodeOs.devNull, nodeOs.constants));
export const arch = () => captureOsCall(() => nodeOs.arch());
export const availableParallelism = () => captureOsCall(() => nodeOs.availableParallelism());
export const cpus = () => captureOsCall(() => serializeOsCpus(nodeOs.cpus()));
export const endianness = () => captureOsCall(() => (nodeOs.endianness() === "BE" ? "be" : "le"));
export const freemem = () => captureOsCall(() => BigInt(nodeOs.freemem()));
export const getPriority = (pid) => captureOsCall(() => nodeOs.getPriority(pid));
export const homedir = () => captureOsCall(() => nodeOs.homedir());
export const hostname = () => captureOsCall(() => nodeOs.hostname());
export const loadavg = () => captureOsCall(() => {
    const [one, five, fifteen] = nodeOs.loadavg();
    return { one, five, fifteen };
});
export const machine = () => captureOsCall(() => nodeOs.machine());
export const networkInterfaces = () => captureOsCall(() => serializeNetworkInterfaces(nodeOs.networkInterfaces()));
export const platform = () => captureOsCall(() => nodeOs.platform());
export const release = () => captureOsCall(() => nodeOs.release());
export const setPriority = (pid, priority) => captureOsCall(() => nodeOs.setPriority(pid, priority));
export const tmpdir = () => captureOsCall(() => nodeOs.tmpdir());
export const totalmem = () => captureOsCall(() => BigInt(nodeOs.totalmem()));
export const type = () => captureOsCall(() => nodeOs.type());
export const uptime = () => captureOsCall(() => nodeOs.uptime());
export const userInfo = (encoding) => captureOsCall(() => {
    // Node intentionally accepts unknown encoding strings and falls back to
    // UTF-8; the guest facade preserves that runtime behavior.
    const value = encoding
        ? nodeOs.userInfo({ encoding: encoding })
        : nodeOs.userInfo();
    return serializeUserInfo(value);
});
export const version = () => captureOsCall(() => nodeOs.version());
const host = {
    getStaticProperties,
    arch,
    availableParallelism,
    cpus,
    endianness,
    freemem,
    getPriority,
    homedir,
    hostname,
    loadavg,
    machine,
    networkInterfaces,
    platform,
    release,
    setPriority,
    tmpdir,
    totalmem,
    type,
    uptime,
    userInfo,
    version,
};
export default host;
